CREATE DATABASE wallab;
\c wallab
CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer    text          NOT NULL,
    amount      numeric(10,2) NOT NULL,
    status      text          NOT NULL DEFAULT 'new',
    created_at  timestamptz   NOT NULL DEFAULT now()
);
INSERT INTO orders (customer, amount)
SELECT 'customer_' || g, (g % 500) + 0.99
FROM generate_series(1, 1000) AS g;

SELECT pg_current_wal_lsn(), pg_current_wal_insert_lsn(),
       pg_current_wal_flush_lsn();
SELECT pg_walfile_name(pg_current_wal_lsn());
SELECT * FROM pg_walfile_name_offset(pg_current_wal_lsn());
SELECT * FROM pg_split_walfile_name('000000010000000000000001');

CHECKPOINT;
SELECT pg_current_wal_lsn() AS before_lsn \gset
UPDATE orders SET status = 'paid' WHERE order_id = 42;
SELECT pg_current_wal_lsn() AS after_lsn \gset
SELECT :'before_lsn' AS before_lsn, :'after_lsn' AS after_lsn,
       pg_wal_lsn_diff(:'after_lsn', :'before_lsn') AS wal_bytes;

SELECT pg_current_wal_lsn() AS before_lsn \gset
UPDATE orders SET status = 'shipped' WHERE order_id = 43;
SELECT pg_current_wal_lsn() AS after_lsn \gset
SELECT :'before_lsn' AS before_lsn, :'after_lsn' AS after_lsn,
       pg_wal_lsn_diff(:'after_lsn', :'before_lsn') AS wal_bytes;

CHECKPOINT;
SELECT pg_current_wal_lsn() AS before_lsn \gset
INSERT INTO orders (customer, amount)
SELECT 'customer_' || g, (g % 500) + 0.99
FROM generate_series(1001, 101000) AS g;
SELECT pg_current_wal_lsn() AS after_lsn \gset
SELECT :'before_lsn' AS before_lsn, :'after_lsn' AS after_lsn,
       pg_size_pretty(pg_wal_lsn_diff(:'after_lsn', :'before_lsn')) AS wal_generated,
       pg_size_pretty(pg_relation_size('orders')) AS table_size,
       pg_size_pretty(pg_indexes_size('orders')) AS index_size;

SELECT pg_stat_reset_shared('wal');
\c wallab
INSERT INTO orders (customer, amount)
SELECT 'customer_' || g, 10.00 FROM generate_series(1, 50000) AS g;
UPDATE orders SET status = 'paid' WHERE order_id <= 20000;
\c postgres
SELECT wal_records, wal_fpi, pg_size_pretty(wal_bytes) AS wal_bytes,
       wal_buffers_full
  FROM pg_stat_wal;
SELECT backend_type, writes, pg_size_pretty(write_bytes) AS written, fsyncs
  FROM pg_stat_io
 WHERE object = 'wal' AND writes > 0
 ORDER BY write_bytes DESC;

SELECT pg_walfile_name(pg_current_wal_lsn()) AS current_file;
SELECT pg_switch_wal();
SELECT pg_walfile_name(pg_current_wal_lsn()) AS current_file;
SELECT pg_switch_wal();
SELECT name, size FROM pg_ls_waldir() ORDER BY name;

CREATE TABLE orders_a AS SELECT * FROM orders WHERE order_id <= 101000;
CREATE TABLE orders_b AS SELECT * FROM orders WHERE order_id <= 101000;
VACUUM orders_a, orders_b;

CHECKPOINT;
SELECT pg_current_wal_lsn() AS before_lsn \gset
UPDATE orders_a SET amount = amount + 1 WHERE order_id % 10 = 0;
SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'before_lsn'))
       AS wal_compression_off;

SET wal_compression = lz4;
CHECKPOINT;
SELECT pg_current_wal_lsn() AS before_lsn \gset
UPDATE orders_b SET amount = amount + 1 WHERE order_id % 10 = 0;
SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'before_lsn'))
       AS wal_compression_lz4;
RESET wal_compression;

CREATE TABLE orders_c AS SELECT * FROM orders WHERE order_id <= 101000;
ALTER TABLE orders_c REPLICA IDENTITY FULL;
VACUUM orders_c;
CHECKPOINT;
SELECT pg_current_wal_lsn() AS before_lsn \gset
UPDATE orders_c SET amount = amount + 1 WHERE order_id % 10 = 0;
SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'before_lsn'))
       AS wal_logical_full;

CHECKPOINT;
INSERT INTO orders (customer, amount) VALUES ('crash_test', 250.00);
SELECT customer, amount FROM orders WHERE customer = 'crash_test';
SELECT pg_current_wal_lsn();

SELECT archived_count, failed_count, last_failed_wal FROM pg_stat_archiver;
SELECT slot_name, active, wal_status,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained
  FROM pg_replication_slots;

